class Task:
    def __init__(self, C, D, T):
        self.C = C
        self.D = D
        self.T = T
        self.u = C / T
        self.lambda_val = C / D

def get_hp_tasks(task_set, task_k, priority_order):
    hp_k = []
    for task_i in task_set:
        if priority_order.index(task_i) < priority_order.index(task_k):
            hp_k.append(task_i)
    return hp_k

def get_gamma_k(task_set, task_k, priority_order):
    hp_k = get_hp_tasks(task_set, task_k, priority_order)
    return hp_k + [task_k]

def calculate_total_utilization(task_list):
    U_total = 0
    for task in task_list:
        U_total += task.u
    return U_total

def is_implicit_deadline_system(task_set):
    for task in task_set:
        if task.D != task.T:
            return False
    return True

import math

def B_m(m):
    if m == 1:
        return 1
    elif m > 1:
        numerator = (3 * m - 2) - math.sqrt(5 * (m**2) - 8 * m + 4)
        denominator = (2 * m - 2)
        return numerator / denominator
    else:
        return 0 # Or raise an error for invalid m

def W_CI_i(L, X, task_i):
    num_ci_jobs = N_CI_i(L, X, task_i)
    return num_ci_jobs * task_i.C

def calculate_max_hp_execution(hp_j, T_j):
    max_execution = 0
    for task_i in hp_j:
        max_execution += task_i.C + (T_j - task_i.C) * task_i.u
    return max_execution

def DA_LC_test_task(task_k, hp_k, m):
    # X_type for N_CI_i is D_i for DA-LC
    X_type = {task.id: task.D for task in hp_k}

    interference = I_k(task_k.D, task_k.C, hp_k, m, X_type)
    R_k = task_k.C + (interference / m)

    return R_k <= task_k.D

def RTA_LC_test_task(task_k, hp_k, m, hp_response_times):
    # X_type for N_CI_i is R_i for RTA-LC
    X_type = {task.id: hp_response_times[task.id] for task in hp_k}

    R_k_current = task_k.C
    R_k_next = 0

    while True:
        interference = I_k(R_k_current, task_k.C, hp_k, m, X_type)
        R_k_next = task_k.C + (interference / m)

        if R_k_next == R_k_current:
            break # Converged
        if R_k_next > task_k.D:
            return False # Unschedulable

        R_k_current = R_k_next

    return R_k_current <= task_k.D
